import { useState, useEffect, useRef } from "react"
import { siteConfig } from "@/config/site"
import { Menu, X, ChevronDown, ChevronRight, ArrowRight } from "lucide-react"

export default function Header() {
  const [megaOpen, setMegaOpen] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)
  const [mobileAccordion, setMobileAccordion] = useState<string | null>(null)
  const [scrolled, setScrolled] = useState(false)
  const megaRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20)
    window.addEventListener("scroll", onScroll)
    return () => window.removeEventListener("scroll", onScroll)
  }, [])

  useEffect(() => {
    if (mobileOpen) {
      document.body.style.overflow = "hidden"
    } else {
      document.body.style.overflow = ""
    }
    return () => { document.body.style.overflow = "" }
  }, [mobileOpen])

  const toggleMobileAccordion = (key: string) => {
    setMobileAccordion(prev => prev === key ? null : key)
  }

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled
          ? "bg-white/95 backdrop-blur-md shadow-sm"
          : "bg-white"
      }`}
    >
      {/* Top accent line */}
      <div className="h-[3px] bg-primary" />

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16 lg:h-20">
          {/* Logo */}
          <a href="index.html" className="flex items-center gap-2 shrink-0">
            <div className="w-8 h-8 bg-primary rounded-sm flex items-center justify-center">
              <span className="text-white font-bold text-sm" style={{ fontFamily: "var(--font-display)" }}>G</span>
            </div>
            <span className="text-xl font-bold text-dark tracking-tight" style={{ fontFamily: "var(--font-display)" }}>
              GlobalStone
            </span>
          </a>

          {/* Desktop Nav */}
          <nav className="hidden lg:flex items-center gap-1">
            {siteConfig.nav.main.map((item) =>
              item.hasMegaMenu ? (
                <div
                  key={item.label}
                  ref={megaRef}
                  className="relative"
                  onMouseEnter={() => setMegaOpen(true)}
                  onMouseLeave={() => setMegaOpen(false)}
                >
                  <button
                    className={`flex items-center gap-1 px-4 py-2 text-sm font-medium rounded transition-colors ${
                      megaOpen
                        ? "text-primary bg-primary/5"
                        : "text-dark/70 hover:text-primary hover:bg-primary/5"
                    }`}
                    onClick={() => setMegaOpen(!megaOpen)}
                  >
                    {item.label}
                    <ChevronDown className={`w-3.5 h-3.5 transition-transform duration-200 ${megaOpen ? "rotate-180" : ""}`} />
                  </button>

                  {/* Mega Menu */}
                  {megaOpen && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 w-[640px] bg-white rounded-lg shadow-2xl border border-border/50 overflow-hidden animate-fade-in">
                      <div className="grid grid-cols-2">
                        <div className="p-6 border-r border-border/30">
                          <h3 className="text-xs font-bold uppercase tracking-wider text-mid-gray mb-4">By Need</h3>
                          <ul className="space-y-1">
                            {siteConfig.nav.megaMenuByNeed.map((link) => (
                              <li key={link.label}>
                                <a
                                  href={link.href}
                                  className="flex items-center justify-between px-3 py-2.5 rounded-md text-sm text-dark/80 hover:bg-primary/5 hover:text-primary transition-colors group"
                                >
                                  {link.label}
                                  <ArrowRight className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                                </a>
                              </li>
                            ))}
                          </ul>
                        </div>
                        <div className="p-6">
                          <h3 className="text-xs font-bold uppercase tracking-wider text-mid-gray mb-4">By Property Type</h3>
                          <ul className="space-y-1">
                            {siteConfig.nav.megaMenuByPropertyType.map((link) => (
                              <li key={link.label}>
                                <a
                                  href={link.href}
                                  className="flex items-center justify-between px-3 py-2.5 rounded-md text-sm text-dark/80 hover:bg-primary/5 hover:text-primary transition-colors group"
                                >
                                  {link.label}
                                  <ArrowRight className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                                </a>
                              </li>
                            ))}
                          </ul>
                        </div>
                      </div>
                      <div className="bg-primary/5 px-6 py-4 border-t border-border/30">
                        <a
                          href="services.html"
                          className="flex items-center gap-2 text-sm font-semibold text-primary hover:text-primary-light transition-colors"
                        >
                          View All Services
                          <ArrowRight className="w-4 h-4" />
                        </a>
                      </div>
                    </div>
                  )}
                </div>
              ) : (
                <a
                  key={item.label}
                  href={item.href}
                  className="px-4 py-2 text-sm font-medium text-dark/70 hover:text-primary hover:bg-primary/5 rounded transition-colors"
                >
                  {item.label}
                </a>
              )
            )}
          </nav>

          {/* Mobile menu button */}
          <button
            className="lg:hidden p-2 text-dark/70 hover:text-primary transition-colors"
            onClick={() => setMobileOpen(!mobileOpen)}
            aria-label={mobileOpen ? "Close menu" : "Open menu"}
          >
