import "@/styles/globals.css"
import { createRoot } from "react-dom/client"
import Header from "@/components/Header"
import Footer from "@/components/Footer"
import { siteConfig } from "@/config/site"
import { useState, useEffect, useRef } from "react"
import { ArrowRight, Play, ChevronRight, BookOpen, Headphones, Mail, ArrowUpRight } from "lucide-react"

/* ─── Hero Section ─── */
function Hero() {
  return (
    <section className="relative min-h-[85vh] flex items-center overflow-hidden">
      {/* Background image overlay */}
      <div
        className="absolute inset-0 bg-cover bg-center"
        style={{
          backgroundImage: `url('https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=1920&q=80')`,
        }}
      >
        <div className="absolute inset-0 bg-gradient-to-r from-dark/90 via-dark/70 to-dark/40" />
      </div>

      <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-32">
        <div className="max-w-2xl">
          <div className="animate-fade-in-up">
            <span className="inline-block px-3 py-1 bg-accent/20 text-accent text-xs font-semibold uppercase tracking-wider rounded mb-6">
              2026 Report
            </span>
          </div>
          <h1
            className="text-4xl sm:text-5xl lg:text-6xl font-bold text-white leading-tight mb-6 animate-fade-in-up delay-100"
            style={{ fontFamily: "var(--font-display)" }}
          >
            {siteConfig.hero.title}
          </h1>
          <p className="text-lg sm:text-xl text-white/70 mb-8 leading-relaxed animate-fade-in-up delay-200">
            {siteConfig.hero.subtitle}
          </p>
          <div className="animate-fade-in-up delay-300">
            <a
              href={siteConfig.hero.cta.href}
              className="inline-flex items-center gap-2 px-8 py-4 bg-accent text-dark font-semibold rounded hover:bg-accent-hover transition-colors text-sm tracking-wide"
            >
              {siteConfig.hero.cta.text}
              <ArrowRight className="w-4 h-4" />
            </a>
          </div>
        </div>
      </div>

      {/* Scroll indicator */}
      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 animate-bounce">
        <div className="w-6 h-10 border-2 border-white/30 rounded-full flex justify-center">
          <div className="w-1 h-2.5 bg-white/60 rounded-full mt-2" />
        </div>
      </div>
    </section>
  )
}

/* ─── Featured Insights ─── */
function FeaturedInsights() {
  return (
    <section className="py-16 lg:py-20 bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {siteConfig.featuredInsights.map((insight, i) => (
            <a
              key={i}
              href={insight.href}
              className="group relative overflow-hidden rounded-xl bg-primary p-6 lg:p-8 text-white hover:bg-primary-light transition-colors"
            >
              <span className="inline-block px-2 py-1 bg-white/15 rounded text-xs font-medium mb-4">
                {i === 0 ? <Headphones className="w-3 h-3 inline mr-1" /> : <BookOpen className="w-3 h-3 inline mr-1" />}
                {insight.tag}
              </span>
              <h3 className="text-lg font-semibold leading-snug mb-4" style={{ fontFamily: "var(--font-display)" }}>
                {insight.title}
              </h3>
              <span className="flex items-center gap-1 text-accent text-sm font-medium group-hover:gap-2 transition-all">
                Listen Now <ArrowRight className="w-3.5 h-3.5" />
              </span>
            </a>
          ))}
        </div>
      </div>
    </section>
  )
}

/* ─── Announcement Banner ─── */
function AnnouncementBanner() {
  return (
    <section className="bg-accent">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex flex-col sm:flex-row items-center justify-between gap-3">
        <p className="text-dark font-semibold text-sm sm:text-base">
          {siteConfig.announcementBanner.text}
        </p>
        <a
          href={siteConfig.announcementBanner.cta.href}
          className="inline-flex items-center gap-1.5 text-dark font-bold text-sm hover:gap-2.5 transition-all shrink-0"
        >
          {siteConfig.announcementBanner.cta.text}
          <ArrowRight className="w-4 h-4" />
        </a>
      </div>
    </section>
  )
}

/* ─── About Statement ─── */
function AboutStatement() {
  return (
    <section className="py-20 lg:py-28 bg-light">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="max-w-3xl mx-auto text-center">
          <h2
            className="text-3xl sm:text-4xl lg:text-5xl font-bold text-dark leading-tight mb-8"
            style={{ fontFamily: "var(--font-display)" }}
          >
            We are the global leader in commercial real estate
          </h2>
          <p className="text-lg text-dark/60 leading-relaxed mb-8">
            {siteConfig.aboutStatement.text}
          </p>
          <a
            href={siteConfig.aboutStatement.cta.href}
            className="inline-flex items-center gap-2 px-8 py-3.5 bg-primary text-white font-semibold rounded hover:bg-primary-light transition-colors text-sm tracking-wide"
          >
            {siteConfig.aboutStatement.cta.text}
            <ArrowRight className="w-4 h-4" />
          </a>
        </div>
      </div>
    </section>
  )
}

/* ─── What We Do (Tabbed Section) ─── */
function WhatWeDo() {
  const [activeTab, setActiveTab] = useState(0)
  const tabs = siteConfig.whatWeDoTabs

  return (
    <section className="py-20 lg:py-28 bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="mb-12 lg:mb-16">
          <h2
            className="text-3xl sm:text-4xl font-bold text-dark"
            style={{ fontFamily: "var(--font-display)" }}
          >
            What We Do
          </h2>
        </div>

        <div className="flex flex-col lg:flex-row gap-8 lg:gap-16">
          {/* Vertical tabs */}
          <div className="flex lg:flex-col gap-2 lg:gap-1 lg:min-w-[260px] overflow-x-auto lg:overflow-visible pb-2 lg:pb-0">
            {tabs.map((tab, i) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(i)}
                className={`flex items-center gap-3 px-5 py-4 rounded-lg text-left whitespace-nowrap lg:whitespace-normal transition-all text-sm font-medium ${
                  activeTab === i
                    ? "bg-primary text-white shadow-lg shadow-primary/20"
                    : "bg-light text-dark/60 hover:bg-primary/5 hover:text-primary"
                }`}
              >
                <span className="text-lg font-bold opacity-40 mr-2">0{i + 1}</span>
                {tab.label}
              </button>
            ))}
          </div>

          {/* Content panel */}
          <div className="flex-1 min-w-0">
            <div
              key={activeTab}
              className="animate-fade-in"
            >
              <div className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-primary/5 to-secondary/5 p-8 lg:p-12">
                <h3
                  className="text-2xl sm:text-3xl font-bold text-dark mb-6"
                  style={{ fontFamily: "var(--font-display)" }}
                >
                  {tabs[activeTab].label}
                </h3>
                <p className="text-dark/60 text-lg leading-relaxed mb-8 max-w-xl">
                  {tabs[activeTab].description}
                </p>
                <a
                  href={tabs[activeTab].cta.href}
                  className="inline-flex items-center gap-2 px-6 py-3 bg-primary text-white font-semibold rounded hover:bg-primary-light transition-colors text-sm"
                >
                  {tabs[activeTab].cta.text}
                  <ArrowRight className="w-4 h-4" />
                </a>

                {/* Decorative element */}
                <div className="absolute -right-8 -bottom-8 w-40 h-40 bg-accent/10 rounded-full blur-3xl" />
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}

/* ─── Newsletter Section ─── */
function Newsletter() {
  return (
    <section className="relative py-20 lg:py-24 bg-secondary overflow-hidden">
      <div className="absolute inset-0 opacity-10">
        <div className="absolute top-0 left-1/4 w-64 h-64 bg-accent rounded-full blur-[120px]" />
        <div className="absolute bottom-0 right-1/4 w-48 h-48 bg-primary-light rounded-full blur-[100px]" />
      </div>

      <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
        <Mail className="w-10 h-10 text-accent mx-auto mb-6" />
        <h2
          className="text-3xl sm:text-4xl font-bold text-white mb-4"
          style={{ fontFamily: "var(--font-display)" }}
        >
          {siteConfig.newsletter.title}
        </h2>
        <p className="text-white/60 text-lg mb-8 max-w-md mx-auto">
          {siteConfig.newsletter.subtitle}
        </p>
        <a
          href={siteConfig.newsletter.cta.href}
          className="inline-flex items-center gap-2 px-8 py-3.5 bg-accent text-dark font-semibold rounded hover:bg-accent-hover transition-colors text-sm"
        >
          {siteConfig.newsletter.cta.text}
          <ArrowRight className="w-4 h-4" />
        </a>
      </div>
    </section>
  )
}

/* ─── Latest Insights ─── */
function LatestInsights() {
  const icons = [BookOpen, BookOpen, Headphones]

  return (
    <section className="py-20 lg:py-28 bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-end justify-between mb-12">
          <h2
            className="text-3xl sm:text-4xl font-bold text-dark"
            style={{ fontFamily: "var(--font-display)" }}
          >
            Latest Insights
          </h2>
          <a href="#" className="hidden sm:inline-flex items-center gap-1 text-sm font-medium text-primary hover:text-primary-light transition-colors">
            View All <ArrowUpRight className="w-3.5 h-3.5" />
          </a>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {siteConfig.latestInsights.map((insight, i) => {
            const Icon = icons[i]
            return (
              <a
                key={i}
                href={insight.href}
                className="group rounded-xl border border-border/50 overflow-hidden hover:shadow-lg hover:shadow-primary/5 transition-all"
              >
                <div className="relative h-44 bg-gradient-to-br from-primary/10 to-secondary/10 flex items-center justify-center">
                  <Icon className="w-10 h-10 text-primary/30" />
                  <span className="absolute top-4 left-4 px-2 py-1 bg-white/90 rounded text-xs font-medium text-primary">
                    {insight.tag}
                  </span>
                </div>
                <div className="p-6">
                  <h3
                    className="text-base font-semibold text-dark leading-snug mb-3 group-hover:text-primary transition-colors"
                    style={{ fontFamily: "var(--font-display)" }}
                  >
                    {insight.title}
                  </h3>
                  <p className="text-xs text-mid-gray">{insight.date}</p>
                </div>
              </a>
            )
          })}
        </div>
      </div>
    </section>
  )
}

/* ─── Our Commitment ─── */
function OurCommitment() {
  return (
    <section className="py-20 lg:py-28 bg-light">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <h2
          className="text-3xl sm:text-4xl font-bold text-dark mb-12 lg:mb-16 text-center"
          style={{ fontFamily: "var(--font-display)" }}
        >
          Our Commitment
        </h2>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {siteConfig.ourCommitment.map((item, i) => (
            <div
              key={i}
              className="bg-white rounded-xl p-6 lg:p-8 border border-border/30 hover:shadow-lg hover:shadow-primary/5 hover:border-accent/30 transition-all group"
            >
              <div className="w-10 h-10 bg-primary/10 rounded-lg flex items-center justify-center mb-5">
                <span className="text-primary font-bold text-sm">0{i + 1}</span>
              </div>
              <h3
                className="text-lg font-bold text-dark mb-3"
                style={{ fontFamily: "var(--font-display)" }}
              >
                {item.title}
              </h3>
              <p className="text-sm text-dark/55 leading-relaxed mb-5">
                {item.description}
              </p>
              <a
                href={item.href}
                className="inline-flex items-center gap-1 text-sm font-medium text-primary hover:text-primary-light transition-colors group-hover:gap-2"
              >
                {item.cta}
                <ArrowRight className="w-3.5 h-3.5" />
              </a>
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}

/* ─── Home Page ─── */
export default function HomePage() {
  return (
    <>
      <Header />
      <main>
        <Hero />
        <FeaturedInsights />
        <AnnouncementBanner />
        <AboutStatement />
        <WhatWeDo />
        <Newsletter />
        <LatestInsights />
        <OurCommitment />
      </main>
      <Footer />
    </>
