                className={`flex items-center gap-3 px-5 py-4 rounded-lg text-left whitespace-nowrap lg:whitespace-normal transition-all text-sm font-medium ${
                  activeTab === i
                    ? "bg-primary text-white shadow-lg shadow-primary/20"
                    : "bg-light text-dark/60 hover:bg-primary/5 hover:text-primary"
                }`}
              >
                <span className="text-lg font-bold opacity-40 mr-2">0{i + 1}</span>
                {tab.label}
              </button>
            ))}
          </div>

          {/* Content panel */}
          <div className="flex-1 min-w-0">
            <div
              key={activeTab}
              className="animate-fade-in"
            >
              <div className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-primary/5 to-secondary/5 p-8 lg:p-12">
                <h3
                  className="text-2xl sm:text-3xl font-bold text-dark mb-6"
                  style={{ fontFamily: "var(--font-display)" }}
                >
                  {tabs[activeTab].label}
                </h3>
                <p className="text-dark/60 text-lg leading-relaxed mb-8 max-w-xl">
                  {tabs[activeTab].description}
                </p>
                <a
                  href={tabs[activeTab].cta.href}
                  className="inline-flex items-center gap-2 px-6 py-3 bg-primary text-white font-semibold rounded hover:bg-primary-light transition-colors text-sm"
                >
                  {tabs[activeTab].cta.text}
                  <ArrowRight className="w-4 h-4" />
                </a>

                {/* Decorative element */}
                <div className="absolute -right-8 -bottom-8 w-40 h-40 bg-accent/10 rounded-full blur-3xl" />
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}

/* ─── Newsletter Section ─── */
function Newsletter() {
  return (
    <section className="relative py-20 lg:py-24 bg-secondary overflow-hidden">
      <div className="absolute inset-0 opacity-10">
        <div className="absolute top-0 left-1/4 w-64 h-64 bg-accent rounded-full blur-[120px]" />
        <div className="absolute bottom-0 right-1/4 w-48 h-48 bg-primary-light rounded-full blur-[100px]" />
      </div>

      <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
        <Mail className="w-10 h-10 text-accent mx-auto mb-6" />
        <h2
          className="text-3xl sm:text-4xl font-bold text-white mb-4"
          style={{ fontFamily: "var(--font-display)" }}
        >
          {siteConfig.newsletter.title}
        </h2>
        <p className="text-white/60 text-lg mb-8 max-w-md mx-auto">
          {siteConfig.newsletter.subtitle}
        </p>
        <a
          href={siteConfig.newsletter.cta.href}
          className="inline-flex items-center gap-2 px-8 py-3.5 bg-accent text-dark font-semibold rounded hover:bg-accent-hover transition-colors text-sm"
        >
          {siteConfig.newsletter.cta.text}
          <ArrowRight className="w-4 h-4" />
        </a>
      </div>
    </section>
  )
}

/* ─── Latest Insights ─── */
function LatestInsights() {
  const icons = [BookOpen, BookOpen, Headphones]

  return (
    <section className="py-20 lg:py-28 bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-end justify-between mb-12">
          <h2
            className="text-3xl sm:text-4xl font-bold text-dark"
            style={{ fontFamily: "var(--font-display)" }}
          >
            Latest Insights
          </h2>
          <a href="#" className="hidden sm:inline-flex items-center gap-1 text-sm font-medium text-primary hover:text-primary-light transition-colors">
            View All <ArrowUpRight className="w-3.5 h-3.5" />
          </a>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {siteConfig.latestInsights.map((insight, i) => {
            const Icon = icons[i]
            return (
              <a
                key={i}
                href={insight.href}
                className="group rounded-xl border border-border/50 overflow-hidden hover:shadow-lg hover:shadow-primary/5 transition-all"
              >
                <div className="relative h-44 bg-gradient-to-br from-primary/10 to-secondary/10 flex items-center justify-center">
                  <Icon className="w-10 h-10 text-primary/30" />
                  <span className="absolute top-4 left-4 px-2 py-1 bg-white/90 rounded text-xs font-medium text-primary">
                    {insight.tag}
                  </span>
                </div>
                <div className="p-6">
                  <h3
                    className="text-base font-semibold text-dark leading-snug mb-3 group-hover:text-primary transition-colors"
                    style={{ fontFamily: "var(--font-display)" }}
                  >
                    {insight.title}
                  </h3>
                  <p className="text-xs text-mid-gray">{insight.date}</p>
                </div>
              </a>
            )
          })}
        </div>
      </div>
    </section>
  )
}

/* ─── Our Commitment ─── */
function OurCommitment() {
  return (
    <section className="py-20 lg:py-28 bg-light">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <h2
          className="text-3xl sm:text-4xl font-bold text-dark mb-12 lg:mb-16 text-center"
          style={{ fontFamily: "var(--font-display)" }}
        >
          Our Commitment
        </h2>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {siteConfig.ourCommitment.map((item, i) => (
            <div
              key={i}
              className="bg-white rounded-xl p-6 lg:p-8 border border-border/30 hover:shadow-lg hover:shadow-primary/5 hover:border-accent/30 transition-all group"
            >
              <div className="w-10 h-10 bg-primary/10 rounded-lg flex items-center justify-center mb-5">
                <span className="text-primary font-bold text-sm">0{i + 1}</span>
              </div>
              <h3
                className="text-lg font-bold text-dark mb-3"
                style={{ fontFamily: "var(--font-display)" }}
              >
                {item.title}
              </h3>
              <p className="text-sm text-dark/55 leading-relaxed mb-5">
                {item.description}
              </p>
              <a
                href={item.href}
                className="inline-flex items-center gap-1 text-sm font-medium text-primary hover:text-primary-light transition-colors group-hover:gap-2"
              >
                {item.cta}
                <ArrowRight className="w-3.5 h-3.5" />
              </a>
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}

/* ─── Home Page ─── */
export default function HomePage() {
  return (
    <>
      <Header />
      <main>
        <Hero />
        <FeaturedInsights />
        <AnnouncementBanner />
        <AboutStatement />
        <WhatWeDo />
        <Newsletter />
        <LatestInsights />
        <OurCommitment />
      </main>
      <Footer />
    </>
  )
}

